//! Golden tests against scikit-image (SSIM, PSNR) and an independent numpy
//! MS-SSIM, generated by `tools/golden/gen_ssim_golden.py`.

mod common;

use common::*;
use lumen_analysis::metrics::MetricOptions;
use std::path::PathBuf;

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/golden")
}

#[test]
fn ssim_psnr_msssim_match_reference_tools() {
    let doc: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(dir().join("golden.json")).unwrap()).unwrap();
    let (w, h, a) = read_pgm(&dir().join(doc["reference"].as_str().unwrap()));
    let o = MetricOptions::default();
    let cases = doc["cases"].as_array().unwrap();
    assert!(cases.len() >= 7);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let (_, _, b) = read_pgm(&dir().join(c["file"].as_str().unwrap()));
        // Gray YUV (native plane) and gray RGBA must agree.
        for (fa, fb) in [(gray_yuv(w, h, a.clone()), gray_yuv(w, h, b.clone())), (gray_rgba(w, h, &a), gray_rgba(w, h, &b))] {
            let (va, vb) = (fa.view(), fb.view());
            let s = run("ssim.gauss", &va, Some(&vb), &o);
            let want = c["ssim"].as_f64().unwrap();
            assert!((val(&s, "y") - want).abs() < 1e-5, "{name}: ssim {} vs skimage {want}", val(&s, "y"));
            let map = s.map.as_ref().unwrap();
            assert_eq!((map.width, map.height), (w as u32 - 10, h as u32 - 10));
            for p in c["ssim_map"].as_array().unwrap() {
                let (y, x, v) = (p[0].as_f64().unwrap() as f32, p[1].as_f64().unwrap() as f32, p[2].as_f64().unwrap());
                let got = map.value_at(x, y).unwrap() as f64;
                assert!((got - v).abs() < 1e-5, "{name}: map({x},{y}) {got} vs {v}");
            }
            let p = run("psnr", &va, Some(&vb), &o);
            let want = c["psnr"].as_f64().unwrap();
            let key = if p.get("y").is_some() { "y" } else { "r" };
            assert!((val(&p, key) - want).abs() < 1e-6, "{name}: psnr {} vs skimage {want}", val(&p, key));
            assert!((val(&p, "avg") - want).abs() < 1e-6);
            let m = run("ms_ssim", &va, Some(&vb), &o);
            let want = c["ms_ssim"].as_f64().unwrap();
            assert!((val(&m, "y") - want).abs() < 1e-5, "{name}: ms-ssim {} vs {want}", val(&m, "y"));
        }
    }
}
